//! Provider-bit vectors: the node/provider split of the signers bitmap.
//!
//! Bits `[0, 64)` are nodes; bits `[64, 256)` are provider signers, whose keys join the aggregate.
//! Every set bit counts toward `signatures_required`, at most one of them a provider bit. The vectors in
//! `fixtures/provider_bits.vectors` are generated by `scripts/gen_provider_vectors.py`, which signs
//! independently of this crate, and are shared with the LiteSVM tests of the Solana program.
//! Format: see the header of the file.

use std::collections::BTreeMap;

use molpha_verifier::{
    coalition_key, resolve_signers, verify, verify_provenance, Attestation, AttestationError,
    AttestationPayload, NodeEntry, RegistryView, SchnorrSignature, PROVIDER_BIT_BASE,
};

const VECTORS: &str = include_str!("fixtures/provider_bits.vectors");
const REDUNDANCY_BUFFER: u8 = 2;

/// A registry of the vectors: node slot `i` is `nodes[i]` (bit `i`), provider slot `p` is
/// `providers[p]` (bit `PROVIDER_BIT_BASE + p`).
struct Registry {
    version: u32,
    buffer: u8,
    nodes: Vec<NodeEntry>,
    providers: Vec<NodeEntry>,
}

struct Case {
    name: String,
    registry: String,
    bitmap: [u8; 32],
    required: u8,
    s: [u8; 32],
    commitment: [u8; 20],
    provider_id: u32,
    verify: Result<(), AttestationError>,
    provenance: Result<(), AttestationError>,
}

struct Vectors {
    value: [u8; 32],
    source_id: [u8; 32],
    timestamp: u64,
    program: String,
    program_bytes: [u8; 32],
    providers: BTreeMap<u32, [u8; 32]>,
    registries: BTreeMap<String, Registry>,
    cases: Vec<Case>,
}

fn unhex<const N: usize>(hex: &str) -> [u8; N] {
    assert_eq!(hex.len(), 2 * N, "{hex}");
    let mut out = [0u8; N];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap();
    }
    out
}

fn outcome(name: &str) -> Result<(), AttestationError> {
    Err(match name {
        "ok" => return Ok(()),
        "InsufficientSigners" => AttestationError::InsufficientSigners,
        "InvalidSignersBitmap" => AttestationError::InvalidSignersBitmap,
        "InvalidAggregateSignature" => AttestationError::InvalidAggregateSignature,
        "ProviderAbsent" => AttestationError::ProviderAbsent,
        other => panic!("unknown outcome {other}"),
    })
}

fn parse() -> Vectors {
    let mut vectors = Vectors {
        value: [0; 32],
        source_id: [0; 32],
        timestamp: 0,
        program: String::new(),
        program_bytes: [0; 32],
        providers: BTreeMap::new(),
        registries: BTreeMap::new(),
        cases: Vec::new(),
    };
    for line in VECTORS
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
    {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "payload" => {
                vectors.value = unhex(f[1]);
                vectors.source_id = unhex(f[2]);
                vectors.timestamp = f[3].parse().unwrap();
            }
            "program" => {
                vectors.program = f[1].to_string();
                vectors.program_bytes = unhex(f[2]);
            }
            "provider" => {
                vectors.providers.insert(f[1].parse().unwrap(), unhex(f[2]));
            }
            "registry" => {
                let node_count: usize = f[4].parse().unwrap();
                let provider_count: usize = f[5].parse().unwrap();
                vectors.registries.insert(
                    f[1].to_string(),
                    Registry {
                        version: f[2].parse().unwrap(),
                        buffer: f[3].parse().unwrap(),
                        nodes: vec![NodeEntry::default(); node_count],
                        providers: vec![NodeEntry::default(); provider_count],
                    },
                );
            }
            "record" => {
                let registry = vectors.registries.get_mut(f[1]).unwrap();
                let bit: usize = f[2].parse().unwrap();
                let entry = NodeEntry {
                    account: unhex(f[3]),
                    x: unhex(f[4]),
                    y: unhex(f[5]),
                };
                if bit < PROVIDER_BIT_BASE {
                    registry.nodes[bit] = entry;
                } else {
                    registry.providers[bit - PROVIDER_BIT_BASE] = entry;
                }
            }
            "case" => vectors.cases.push(Case {
                name: f[1].to_string(),
                registry: f[2].to_string(),
                bitmap: unhex(f[3]),
                required: f[4].parse().unwrap(),
                s: unhex(f[5]),
                commitment: unhex(f[6]),
                provider_id: f[7].parse().unwrap(),
                verify: outcome(f[8]),
                provenance: outcome(f[9]),
            }),
            other => panic!("unknown record {other}"),
        }
    }
    for (name, registry) in &vectors.registries {
        for table in [&registry.nodes, &registry.providers] {
            assert!(
                table.last().is_none_or(|last| !last.is_vacant()),
                "{name}: trailing holes are never stored"
            );
        }
        assert_eq!(registry.buffer, REDUNDANCY_BUFFER);
    }
    vectors
}

fn view(registry: &Registry) -> RegistryView<'_> {
    RegistryView {
        version: registry.version,
        node_count: registry.nodes.len() as u16,
        provider_count: registry.providers.len() as u16,
        redundancy_buffer: registry.buffer,
        nodes: &registry.nodes,
        providers: &registry.providers,
    }
}

fn attestation(vectors: &Vectors, registry: &Registry, case: &Case) -> Attestation {
    Attestation {
        payload: AttestationPayload {
            value: vectors.value,
            source_id: vectors.source_id,
            registry_version: registry.version,
            timestamp: vectors.timestamp,
            signatures_required: case.required,
        },
        signature: SchnorrSignature {
            agg_sig_s: case.s,
            commitment: case.commitment,
            signers_bitmap: case.bitmap,
        },
    }
}

#[test]
fn the_vectors_cover_the_rules() {
    let vectors = parse();
    assert!(vectors.cases.len() >= 22);
    for expected in [
        "nodes-only",
        "provider-7-present",
        "provider-7-names-9",
        "provider-counts",
        "provider-short-by-one",
        "two-providers-names-7",
        "two-providers-are-refused-not-counted",
        "provider-only-t1",
        "provider-only-required-0",
        "provider-bit-on-hole",
        "provider-key-missing-from-signature",
        "reused-slot-names-old-holder",
    ] {
        assert!(
            vectors.cases.iter().any(|c| c.name == expected),
            "missing case {expected}"
        );
    }
}

#[test]
fn verify_and_verify_provenance_match_the_vectors() {
    let vectors = parse();
    for case in &vectors.cases {
        let registry = &vectors.registries[&case.registry];
        let attestation = attestation(&vectors, registry, case);
        let registry = view(registry);
        let provider = vectors.providers[&case.provider_id];

        assert_eq!(
            verify(&attestation, &registry, None),
            case.verify,
            "{}: verify",
            case.name
        );
        assert_eq!(
            verify_provenance(&attestation, &registry, None, &provider),
            case.provenance,
            "{}: verify_provenance",
            case.name
        );

        // The reporter-supplied coalition key changes the cost of verification, never its verdict.
        if let Ok(signers) = resolve_signers(&registry, &attestation.signature.signers_bitmap) {
            let key = coalition_key(&signers).unwrap();
            assert_eq!(
                verify(&attestation, &registry, Some(&key)),
                case.verify,
                "{}: verify with key",
                case.name
            );
            assert_eq!(
                verify_provenance(&attestation, &registry, Some(&key), &provider),
                case.provenance,
                "{}: verify_provenance with key",
                case.name
            );
        }
    }
}

/// The provider is found only after the signature verified: the same record in a bitmap whose
/// aggregate is wrong never reads as present.
#[test]
fn provenance_is_never_read_off_an_unverified_signature() {
    let vectors = parse();
    for case in vectors
        .cases
        .iter()
        .filter(|c| c.verify == Err(AttestationError::InvalidAggregateSignature))
    {
        let registry = &vectors.registries[&case.registry];
        let provider = vectors.providers[&case.provider_id];
        assert_eq!(
            verify_provenance(
                &attestation(&vectors, registry, case),
                &view(registry),
                None,
                &provider
            ),
            Err(AttestationError::InvalidAggregateSignature),
            "{}",
            case.name
        );
    }
}

#[test]
fn a_provenance_check_names_the_registry_version_of_the_attestation() {
    let vectors = parse();
    let case = vectors
        .cases
        .iter()
        .find(|c| c.name == "provider-7-present")
        .unwrap();
    let registry = &vectors.registries[&case.registry];
    let provider = vectors.providers[&case.provider_id];
    let mut stale = attestation(&vectors, registry, case);
    stale.payload.registry_version += 1;
    assert_eq!(
        verify_provenance(&stale, &view(registry), None, &provider),
        Err(AttestationError::InvalidRegistryVersion)
    );
}

/// A vacant record's account is the zero address, which names no provider.
#[test]
fn the_zero_account_is_never_a_provider() {
    let vectors = parse();
    let case = vectors
        .cases
        .iter()
        .find(|c| c.name == "provider-7-present")
        .unwrap();
    let registry = &vectors.registries[&case.registry];
    assert_eq!(
        verify_provenance(
            &attestation(&vectors, registry, case),
            &view(registry),
            None,
            &[0u8; 32]
        ),
        Err(AttestationError::ProviderAbsent)
    );
}

#[cfg(feature = "solana")]
#[test]
fn provider_accounts_are_the_program_pdas() {
    use molpha_verifier::solana::{provider_account, PROGRAM_ID};

    let vectors = parse();
    assert_eq!(vectors.program, PROGRAM_ID.to_string());
    assert_eq!(vectors.program_bytes, PROGRAM_ID.to_bytes());
    for (id, account) in &vectors.providers {
        assert_eq!(*account, provider_account(*id).to_bytes(), "provider {id}");
    }
}

/// The same vectors through the account path: a `Registry` account holding the two tables, and the
/// provider PDA derived from the ID the source names.
#[cfg(feature = "solana")]
mod account_path {
    use super::*;
    use molpha_verifier::solana::{
        registry_account_len, verify_attestation, verify_provenance, AccountError,
        DISCRIMINATOR_LEN, PROGRAM_ID, REGISTRY_DISCRIMINATOR, REGISTRY_MEMBER_LEN,
        REGISTRY_NODES_OFFSET,
    };
    use solana_account_info::AccountInfo;
    use solana_pubkey::Pubkey;

    /// Registry bytes in the program's layout: discriminator, `grace_active_until` and
    /// `active_from` (i64), `version` (u32), `node_count` and `provider_count` (u8),
    /// `redundancy_buffer` and `bump`, then the node table and the provider table.
    fn registry_data(registry: &Registry) -> Vec<u8> {
        let records = registry.nodes.len() + registry.providers.len();
        let mut data = vec![0u8; registry_account_len(records)];
        data[..DISCRIMINATOR_LEN].copy_from_slice(&REGISTRY_DISCRIMINATOR);
        data[24..28].copy_from_slice(&registry.version.to_le_bytes());
        data[28] = registry.nodes.len() as u8;
        data[29] = registry.providers.len() as u8;
        data[30] = registry.buffer;
        for (index, entry) in registry.nodes.iter().chain(&registry.providers).enumerate() {
            let offset = REGISTRY_NODES_OFFSET + index * REGISTRY_MEMBER_LEN;
            data[offset..offset + 32].copy_from_slice(&entry.account);
            data[offset + 32..offset + 64].copy_from_slice(&entry.x);
            data[offset + 64..offset + 96].copy_from_slice(&entry.y);
        }
        data
    }

    #[test]
    fn verify_provenance_from_the_registry_account_matches_the_vectors() {
        let vectors = parse();
        for case in &vectors.cases {
            let registry = &vectors.registries[&case.registry];
            let attestation = attestation(&vectors, registry, case);
            let mut data = registry_data(registry);
            let key = Pubkey::new_unique();
            let mut lamports = 1u64;
            let info = AccountInfo::new(
                &key,
                false,
                false,
                &mut lamports,
                &mut data,
                &PROGRAM_ID,
                false,
            );

            let attest = |e: AccountError| match e {
                AccountError::Attestation(e) => e,
                other => panic!("{}: unexpected {other:?}", case.name),
            };
            assert_eq!(
                verify_attestation(&attestation, &info, None).map_err(attest),
                case.verify,
                "{}: verify_attestation",
                case.name
            );
            assert_eq!(
                verify_provenance(&attestation, &info, None, case.provider_id).map_err(attest),
                case.provenance,
                "{}: solana::verify_provenance",
                case.name
            );
        }
    }
}
